SELECT num, title, content, imgn, hit, created_date, updated_date, member_num, row_num FROM ( SELECT num, title, content, imgn, hit, created_date, updated_date, member_num, ROW_NUMBER() OVER(ORDER BY num DESC) AS row_num FROM notice
title LIKE '%' || #{searchValue} || '%'
content LIKE '%' || #{searchValue} || '%'
) numbered_rows WHERE row_num BETWEEN #{begin} AND #{end}

SELECT num, title, content, imgn, hit, created_date, updated_date,
member_num
FROM notice WHERE num=#{num}
